import{_ as t,o as a,c as o,ae as r}from"./chunks/framework.Bs_1Tt6f.js";const u=JSON.parse('{"title":"Settings & Data Backup","description":"","frontmatter":{},"headers":[],"relativePath":"docs/settings-and-data.md","filePath":"docs/settings-and-data.md"}'),n={name:"docs/settings-and-data.md"};function s(i,e,d,p,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="settings-data-backup" tabindex="-1">Settings &amp; Data Backup <a class="header-anchor" href="#settings-data-backup" aria-label="Permalink to &quot;Settings &amp; Data Backup&quot;">​</a></h1><p>The <strong>Settings</strong> view holds everything about <em>where your work is kept</em>, how to back it up and move it, and the project-wide options that shape the other views.</p><h2 id="where-your-work-is-kept" tabindex="-1">Where your work is kept <a class="header-anchor" href="#where-your-work-is-kept" aria-label="Permalink to &quot;Where your work is kept&quot;">​</a></h2><p>Your annotations, equivalents tables, pattern library and settings are kept in two places:</p><ol><li><strong>Browser storage</strong> is the working copy. It is fast, but browsers may clear it (clearing site data, private windows, low disk space).</li><li><strong>A workspace folder</strong> (Settings → <strong>Project Folder</strong>, Chrome / Edge) is the permanent copy. Once a folder is chosen, every change is saved into it automatically.</li></ol><p>The status pill in the toolbar shows where things stand: <em>Saved</em>, <em>Saving…</em>, <em>No changes</em>, <em>Not saved</em> (browser storage is full) or <em>Not saving</em> (the folder&#39;s file cannot be used — nothing is written to it until you fix that).</p><h3 id="what-is-in-the-folder" tabindex="-1">What is in the folder <a class="header-anchor" href="#what-is-in-the-folder" aria-label="Permalink to &quot;What is in the folder&quot;">​</a></h3><table tabindex="0"><thead><tr><th>File</th><th>Contents</th></tr></thead><tbody><tr><td><code>workspace.json</code></td><td>settings, annotations, equivalents, pattern library, OMMR settings</td></tr><tr><td><code>direct-snippets.json</code></td><td>the image snippets of <a href="./custom-manuscripts.html">Custom Manuscripts</a> (kept separate because images are large)</td></tr></tbody></table><p>The app only ever writes these files when it can read them. A file that is damaged, or was written by a <strong>newer</strong> version of the app, is <strong>left untouched</strong> and saving is switched off with a message, so the app can never overwrite something it does not understand.</p><h3 id="safety-copies-you-may-find" tabindex="-1">Safety copies you may find <a class="header-anchor" href="#safety-copies-you-may-find" aria-label="Permalink to &quot;Safety copies you may find&quot;">​</a></h3><p>The app keeps a copy before it replaces anything. These files are never deleted by the app:</p><table tabindex="0"><thead><tr><th>File</th><th>Why it exists</th></tr></thead><tbody><tr><td><code>workspace.pre-v1.json</code></td><td>your file exactly as it was before this version upgraded it to its newer format</td></tr><tr><td><code>workspace.backup-external.json</code></td><td>the previous <code>workspace.json</code>, kept when it had been changed outside this tab (another tab, another computer) before the app replaced it</td></tr><tr><td><code>workspace.replaced-&lt;time&gt;.json</code></td><td>what the app held in the browser when the folder&#39;s own workspace was loaded instead (choosing a folder that already had one, or meeting a folder for the first time). <strong>Import</strong> it to get that work back</td></tr></tbody></table><p>Do not open the same folder in two browser tabs or two computers at once; the second one will keep the other&#39;s version as <code>workspace.backup-external.json</code>, but the two are not merged.</p><h2 id="backups-and-moving-work-between-computers" tabindex="-1">Backups and moving work between computers <a class="header-anchor" href="#backups-and-moving-work-between-computers" aria-label="Permalink to &quot;Backups and moving work between computers&quot;">​</a></h2><p>Under <strong>Share / Backup</strong>:</p><ul><li><strong>Export Manuscripts</strong> downloads all manuscripts that have data as one JSON file. Tick <em>Include Settings</em> to add your configuration, pattern library and OMMR settings.</li><li><strong>Specific Manuscript(s)</strong> exports only the ones you pick.</li><li><strong>Export Config / Import Config</strong> move only the configuration (display mode, preferred IDs, custom signs, alignments, …), without any annotations.</li><li><strong>Import Backup / Manuscript File</strong> reads any file the app has exported — also from older versions of the app. If a manuscript in the file already exists in your workspace you choose, per manuscript, to <strong>overwrite</strong> it, keep both (<strong>copy</strong>) or <strong>skip</strong> it. A file written by a <em>newer</em> version is refused instead of being guessed at.</li><li><strong>Remove All Data</strong> wipes the manuscript data from this workspace. Export a backup first; it cannot be undone.</li></ul><h3 id="backup-reminder" tabindex="-1">Backup reminder <a class="header-anchor" href="#backup-reminder" aria-label="Permalink to &quot;Backup reminder&quot;">​</a></h3><p>When you have made a number of changes and have not exported for a while, a small reminder appears. Under <strong>Backup Reminder</strong> you can change when, or turn it off. With a workspace folder bound, the folder is your backup and the reminder matters less.</p><h2 id="app-defaults-and-project-settings" tabindex="-1">App Defaults and project settings <a class="header-anchor" href="#app-defaults-and-project-settings" aria-label="Permalink to &quot;App Defaults and project settings&quot;">​</a></h2><ul><li><strong>App Defaults</strong> — how patterns are drawn everywhere: <em>Graphic (SVG)</em>, <em>Arrows (↗/↘)</em> or <em>Text (u/d/e)</em>.</li><li><strong>Preferred Custom IDs</strong> — define a default Ref ID for a pattern (e.g. <code>*dd</code> → <code>Type A</code>). When you link a polygon to an occurrence of that pattern, the ID is filled in for you; you can still override it.</li><li><strong>Source Metadata</strong> — define your own attributes for manuscripts (century, region, …) and fill them in per manuscript. They become filters in the public views.</li><li><strong>Custom Signs &amp; Code Variants</strong> — define special signs (for example a virga) and the pattern variants derived from them. The switch <em>discriminate signs</em> decides whether variants are counted separately or merged into their base pattern.</li><li><strong>Manuscript Alignment</strong> — tell the app how the folios of the transcription map onto the pages of the IIIF manifest, including jumps where the manifest skips images.</li></ul><h2 id="shared-sync-monodi-app" tabindex="-1">Shared Sync (monodi.app) <a class="header-anchor" href="#shared-sync-monodi-app" aria-label="Permalink to &quot;Shared Sync (monodi.app)&quot;">​</a></h2><p>The <strong>Shared Sync</strong> panel connects the app to the GitHub repository your project shares with monodi.app (an access token with read/write <em>Contents</em> permission on that repository; it is kept only in this browser and sent only to GitHub).</p><ul><li><strong>Pull</strong> brings in source records, equivalents and annotations. It <strong>adds and updates and never removes</strong> what you have here.</li><li><strong>Push</strong> writes your equivalents, line regions and snippets back, changing only manuscripts whose data actually changed. It never removes anything in the repository and it never overwrites a newer commit.</li><li><strong>Export / Import database file</strong> exchanges the same data as one file when there is no repository.</li></ul><p>Snippets that belong to no line (shown under &quot;Unassigned&quot; in the annotation view) are not pushed.</p>',24)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
